# name: participant_spread_balance_pref
# description: Standard deviation across participants of each participant's proportion choosing the more H/T-balanced sequence among pairs whose imbalance differs by at least 0.25; observed above the null means people differ in how much they weight balance more than the model's single shared balance weight allows.
def test_statistic(df):
    def imb(s):
        return abs(s.count("H") - s.count("T")) / len(s)
    u = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    f = {s: imb(s) for s in u}
    ia = df["sequence_a"].map(f).to_numpy(float)
    ib = df["sequence_b"].map(f).to_numpy(float)
    diff = ib - ia
    m = np.abs(diff) >= 0.25 - 1e-9
    if m.sum() == 0:
        return 0.0
    chose_bal = np.where(diff[m] > 0, df["chose_left"].to_numpy(float)[m], 1 - df["chose_left"].to_numpy(float)[m])
    rates = pd.Series(chose_bal).groupby(df["participant_id"].to_numpy()[m]).mean()
    return float(rates.std(ddof=0))

# name: short_seq_alt_agreement
# description: Among trials with sequence length <= 5 whose alternation rates differ, the proportion choosing the higher-alternation sequence minus the same proportion among length-8 trials; observed above the null means short sequences are judged by alternation more (or long ones less) than the model's length-independent sensitivity predicts, below means the reverse.
def test_statistic(df):
    def alt(s):
        return sum(1 for x, y in zip(s, s[1:]) if x != y) / (len(s) - 1)
    u = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    f = {s: alt(s) for s in u}
    aa = df["sequence_a"].map(f).to_numpy(float)
    ab = df["sequence_b"].map(f).to_numpy(float)
    L = df["sequence_a"].str.len().to_numpy()
    y = df["chose_left"].to_numpy(float)
    d = aa - ab
    hi = np.where(d > 0, y, 1 - y)
    ms = (L <= 5) & (np.abs(d) > 1e-9)
    ml = (L == 8) & (np.abs(d) > 1e-9)
    if ms.sum() == 0 or ml.sum() == 0:
        return 0.0
    return float(hi[ms].mean() - hi[ml].mean())

# name: trial_drift_alt_pref
# description: Proportion choosing the higher-alternation sequence (among pairs with different alternation rates) in the second half of each participant's trials minus the first half; nonzero observed vs a ~0 null means preferences drift over the session (learning, fatigue, or becoming noisier), which the stationary model does not predict.
def test_statistic(df):
    def alt(s):
        return sum(1 for x, y in zip(s, s[1:]) if x != y) / (len(s) - 1)
    u = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    f = {s: alt(s) for s in u}
    d = df["sequence_a"].map(f).to_numpy(float) - df["sequence_b"].map(f).to_numpy(float)
    y = df["chose_left"].to_numpy(float)
    hi = np.where(d > 0, y, 1 - y)
    med = df.groupby("participant_id")["trial_index"].transform("median").to_numpy(float)
    late = df["trial_index"].to_numpy(float) > med
    m = np.abs(d) > 1e-9
    if (m & late).sum() == 0 or (m & ~late).sum() == 0:
        return 0.0
    return float(hi[m & late].mean() - hi[m & ~late].mean())

# name: participant_side_bias_spread
# description: Standard deviation across participants of each participant's proportion of Left choices; observed above the null means individuals have response-side biases (habitual Left or Right clicking) that the side-neutral model does not produce.
def test_statistic(df):
    r = df.groupby("participant_id")["chose_left"].mean()
    return float(r.std(ddof=0))
